console.log('\n=== D: 実機の見本 (RumiCar-lib v0.7.0・RasPi master 061e42a・Zero2Cam v0.7.0 の本文そのまま) を本番 runRace で ===');
{
  const EX = {
    ino25: "#include <RumiCar.h>\n\nvoid setup()\n{\n  RC_setup();\n}\n\nvoid loop()\n{\n  RC_steer(RIGHT,255);\n  delay(500);\n  RC_steer(LEFT,255);\n  delay(500);\n  RC_steer(RIGHT,128);\n  delay(500);\n  RC_steer(LEFT,128);\n  delay(500);\n}\n",
    ino33: "#include <RumiCar.h>\n\nint ipower = 128;       // steering strength 0-255 (start at half)\nint lastTurn = CENTER;  // the side we steered to last time\nint lastGap = 0;        // left/right difference last time [mm]\n\nvoid setup()\n{\n  RC_setup();\n  RC_setReadLimit(200); // the distance RC_read trusts [mm]. Beyond it RC_read returns -3 (far)\n}\n\nvoid loop()\n{\n\n  int iband = 30;       // if left and right differ by this much or less, go straight [mm]\n  int s0, s1, s2;\n  s0=RC_read(LEFT);\n  s1=RC_read(CENTER);\n  s2=RC_read(RIGHT);\n  if(s0==-3) s0=250;    // -3: farther than the limit = open road (-3 is the smallest number, so replace it first)\n  if(s1==-3) s1=250;\n  if(s2==-3) s2=250;\n\n\n  Serial.print(\"Sensor0:\");\n  Serial.print(s0);\n  Serial.print(\"  Sensor1:\");\n  Serial.print(s1);\n  Serial.print(\"  Sensor2:\");\n  Serial.print(s2);\n  Serial.print(\"  Power:\");\n  Serial.println(ipower);\n\n  if(s0==-1 || s1==-1 || s2==-1){\n    return;             // -1: a sensor did not answer, keep driving as before\n  }\n\n  if(s1<100){           // keep these thresholds at or below the limit in setup()\n    RC_drive(REVERSE,150);\n  }else if (s1<150){\n    RC_drive(FORWARD,150);\n  }else if (s1<200){\n    RC_drive(FORWARD,200);\n  }else{\n    RC_drive(FORWARD,255);\n  }\n\n  int gap = abs(s0-s2);\n  if(gap<=iband){\n    RC_steer(CENTER);\n  }else{\n    int side;\n    if(s0>s2){\n      side=LEFT;\n    }else{\n      side=RIGHT;\n    }\n    if(lastTurn!=CENTER && side!=lastTurn){\n      ipower=ipower/2;        // went past the middle: too strong, use half\n    }else if(side==lastTurn && gap>=lastGap){\n      ipower=ipower*13/10;    // not getting closer to the middle: too weak, use 1.3 times\n    }\n    ipower=constrain(ipower,40,255);  // keep at least 40 so that 1.3 times can grow again\n    RC_steer(side,ipower);\n    lastTurn=side;\n  }\n  lastGap=gap;\n}\n",
    ino42a: "#include <RumiCar.h>\n\n// Exercise-4.2-Answer はまったら切り返す車（解答例）\n//   Exercise-3.2 の走り方に、「はまったことに気づく」3 つの方法と、\n//   「ハンドルを切り返して脱出する」手順を足したものです。\n//   使えるのは前・左・右の距離センサーと、自分がモーターに何を命じたかだけです。\n//\n//   はまりの検知（どれか 1 つでも成立したら脱出に入る）\n//     (1) 前後の切り替えが短い時間に何回も起きた\n//     (2) 前進や後進を命じているのに、前の距離がほとんど変わらない\n//     (3) 前・左・右がすべて近い（角に鼻先が入っている）\n//   脱出（切り返し）\n//     近い壁の側にハンドルを切って少し後退 → 遠い側に切って少し前進 → 前が開いたか確かめる。\n//     後退するときは「近い壁の側」にハンドルを切るのがコツです（鼻先が壁から離れる向きに振れる）。\n//     決めた回数で抜けられなければ止まって待ち、前が開いたら走行を再開します。\n//   数値はすべて目安です。自分の車体とコースに合わせて変えてみましょう。\n\n// ---- 3.2 と同じ走り方のパラメータ ----\nconst int PWM_SLOW   = 150;\nconst int PWM_MID    = 200;\nconst int PWM_FAST   = 255;\n\n// ---- はまりの検知 ----\nconst unsigned long FLIP_WINDOW_MS = 3000;  // (1) この時間の中で\nconst int           FLIP_LIMIT     = 4;     // (1) 前後が何回入れ替わったら「はまり」か\nconst unsigned long STALL_CHECK_MS = 1000;  // (2) 前の距離を比べる間隔 [ms]\nconst int           STALL_DELTA_MM = 20;    // (2) これより変化が小さければ「進んでいない」（測距誤差 1〜2cm を考慮）\nconst int           STALL_NEAR_MM  = 200;   // (2) 前がこれより近いときだけ判定する（遠い壁は見ない。上限（RC_setReadLimit）以下にする）\nconst int           STALL_LIMIT    = 2;     // (2) 何回続いたら「はまり」か（最初の 1 回は比べる相手が無いので検知まで約 3 秒）\nconst int           CORNER_MM      = 120;   // (3) 前・左・右がすべてこれ未満なら角に入っている\n\n// ---- 脱出（切り返し） ----\nconst int           ESCAPE_PWM     = 200;   // 切り返しの速さ\nconst unsigned long BACK_MS        = 600;   // 後退する時間 [ms]\nconst unsigned long FWD_MS         = 400;   // 前進する時間 [ms]\nconst int           ESCAPE_TRIES   = 3;     // 切り返しの最大回数\nconst int           CLEAR_MM       = 200;   // 前がこれ以上開いたら脱出成功（上限（RC_setReadLimit）以下にする）\nconst int           REAR_STOP_MM   = 80;    // 後方センサーがある車体：後ろがこれより近ければ後退をやめる\nconst unsigned long COOLDOWN_MS    = 2000;  // 脱出のあと、再びはまりを判定しない時間 [ms]\n\n// ---- 状態を覚えておく変数 ----\nint           lastDirec   = FREE;   // 直前に命じた走行方向（FORWARD / REVERSE）\nunsigned long flipStart   = 0;      // (1) 数え始めた時刻\nint           flipCount   = 0;      // (1) 前後の切り替え回数\nunsigned long stallTime   = 0;      // (2) 前回比べた時刻\nint           stallPrev   = -1;     // (2) 前回の前の距離（-1 = まだ無い）\nint           stallCount  = 0;      // (2) 「進んでいない」が続いた回数\nunsigned long cooldownEnd = 0;      // 脱出のあと、この時刻までは判定しない\n\nvoid setup()\n{\n  RC_setup();\n  RC_setReadLimit(200);   // 信じる距離の上限 [mm]。これより先は -3（遠い）。上のしきい値はこの値以下にする\n}\n\n// 距離が測れなかったとき（-1 や -3）は「遠い」として扱う（3.2 の 8190 と同じ考え方）\n// RC_read は上限（setup() の RC_setReadLimit）より先を -3（範囲外）にするので、-3 は「上限より手前に何もない」\nint farIfInvalid(int d)\n{\n  return (d < 0) ? 9999 : d;\n}\n\n// 前が開いているか（遠い、または測れないほど遠い）\nbool isClear(int s1)\n{\n  return (s1 == -3) || (s1 >= CLEAR_MM);\n}\n\n// RC_drive の代わりに使う。前後の切り替え回数を数える（検知 (1) のため）\nvoid driveAndCount(int direc, int pwm)\n{\n  if ((direc == FORWARD && lastDirec == REVERSE) ||\n      (direc == REVERSE && lastDirec == FORWARD)) {\n    unsigned long now = millis();\n    if (flipCount == 0 || now - flipStart > FLIP_WINDOW_MS) {   // 数え直し\n      flipStart = now;\n      flipCount = 0;\n    }\n    flipCount++;\n  }\n  if (direc == FORWARD || direc == REVERSE) {\n    lastDirec = direc;\n  }\n  RC_drive(direc, pwm);\n}\n\n// (1) 前後の切り替えが短い時間に何回も起きたか\nbool stuckByFlip()\n{\n  return (flipCount >= FLIP_LIMIT) && (millis() - flipStart <= FLIP_WINDOW_MS);\n}\n\n// (2) 前進や後進を命じているのに、前の距離がほとんど変わらないか\nbool stuckByNoProgress(int s1)\n{\n  unsigned long now = millis();\n  if (now - stallTime < STALL_CHECK_MS) {\n    return false;                                    // まだ比べる時刻ではない\n  }\n  stallTime = now;\n  bool moving = (lastDirec == FORWARD || lastDirec == REVERSE);\n  bool near   = (s1 >= 0 && s1 < STALL_NEAR_MM);     // 測れていて、しかも近い\n  if (moving && near && stallPrev >= 0 && abs(s1 - stallPrev) < STALL_DELTA_MM) {\n    stallCount++;\n  } else {\n    stallCount = 0;\n  }\n  stallPrev = near ? s1 : -1;\n  return stallCount >= STALL_LIMIT;\n}\n\n// (3) 前・左・右がすべて近いか（角に鼻先が入っている）\nbool stuckByThreeSides(int s0, int s1, int s2)\n{\n  return (lastDirec == FORWARD) &&\n         (s0 >= 0 && s0 < CORNER_MM) &&\n         (s1 >= 0 && s1 < CORNER_MM) &&\n         (s2 >= 0 && s2 < CORNER_MM);\n}\n\nvoid resetDetectors()\n{\n  flipCount  = 0;\n  stallCount = 0;\n  stallPrev  = -1;\n  stallTime  = millis();\n  cooldownEnd = millis() + COOLDOWN_MS;\n}\n\n// 切り返して脱出する\nvoid escape(int s0, int s2)\n{\n  // 近い壁の側を決める（測れない側は「遠い」とみなす）\n  int nearSide = (farIfInvalid(s0) < farIfInvalid(s2)) ? LEFT : RIGHT;\n  int farSide  = (nearSide == LEFT) ? RIGHT : LEFT;\n\n  for (int i = 0; i < ESCAPE_TRIES; i++) {\n    // 後退：近い壁の側にハンドルを切る（鼻先が壁から離れる）\n    RC_steer(nearSide);\n    RC_drive(REVERSE, ESCAPE_PWM);\n    unsigned long t0 = millis();\n    while (millis() - t0 < BACK_MS) {\n      int rear = RC_read(REAR);                       // 後方センサーが無い車体は -1 が返る\n      if (rear >= 0 && rear < REAR_STOP_MM) {\n        break;                                        // 後ろが近い：後退をやめる\n      }\n    }\n    RC_drive(BRAKE, 0);\n    delay(100);\n\n    // 前進：遠い側にハンドルを切る\n    RC_steer(farSide);\n    RC_drive(FORWARD, ESCAPE_PWM);\n    delay(FWD_MS);\n    RC_drive(BRAKE, 0);\n    delay(100);\n\n    // 前が開いたか確かめる\n    if (isClear(RC_read(CENTER))) {\n      Serial.println(\"ESCAPED\");\n      lastDirec = FORWARD;\n      resetDetectors();\n      return;\n    }\n  }\n\n  // 抜けられなかった：止まって待ち、前が開いたら再開する（手で助けてもらう）\n  RC_drive(FREE, 0);\n  Serial.println(\"GIVE UP: waiting\");\n  while (!isClear(RC_read(CENTER))) {\n    delay(100);\n  }\n  lastDirec = FORWARD;\n  resetDetectors();\n}\n\n// Exercise-3.2 と同じ走り方\nvoid driveLikeExercise32(int s0, int s1, int s2)\n{\n  int d0 = farIfInvalid(s0);\n  int d1 = farIfInvalid(s1);\n  int d2 = farIfInvalid(s2);\n\n  if (d1 < 100) {\n    driveAndCount(REVERSE, PWM_SLOW);\n  } else if (d1 < 150) {\n    driveAndCount(FORWARD, PWM_SLOW);\n  } else if (d1 < 200) {\n    driveAndCount(FORWARD, PWM_MID);\n  } else {\n    driveAndCount(FORWARD, PWM_FAST);\n  }\n  if (d0 > d2) {\n    RC_steer(LEFT);\n  } else {\n    RC_steer(RIGHT);\n  }\n}\n\nvoid loop()\n{\n  int s0 = RC_read(LEFT);\n  int s1 = RC_read(CENTER);\n  int s2 = RC_read(RIGHT);\n\n  Serial.print(\"L:\");  Serial.print(s0);\n  Serial.print(\" C:\"); Serial.print(s1);\n  Serial.print(\" R:\"); Serial.print(s2);\n  Serial.print(\" flips:\"); Serial.print(flipCount);\n  Serial.print(\" stall:\"); Serial.println(stallCount);\n\n  bool canJudge = (millis() >= cooldownEnd);   // 脱出の直後は判定しない\n  if (canJudge && (stuckByFlip()\n                   || stuckByNoProgress(s1)\n                   || stuckByThreeSides(s0, s1, s2))) {\n    Serial.println(\"STUCK\");\n    escape(s0, s2);                           // 切り返し（最大 ESCAPE_TRIES 回）\n    return;\n  }\n\n  driveLikeExercise32(s0, s1, s2);            // 3.2 と同じ走り方\n}\n",
    py25: "from RumiCar import *\nimport time\n\n# ハンドルの強さを変えてみよう: 強さ 255 (いちばん強い) と 128 (半分) で右・左に切る\n# 実行: python3 ../RumiCar.py Exercise-2.5.py\n\n\ndef setup():\n    RC_setup()\n\n\ndef loop():\n    RC_steer(RIGHT, 255)\n    time.sleep(0.5)\n    RC_steer(LEFT, 255)\n    time.sleep(0.5)\n    RC_steer(RIGHT, 128)\n    time.sleep(0.5)\n    RC_steer(LEFT, 128)\n    time.sleep(0.5)\n",
    py31: "from RumiCar import *\n\n# 安全に止まる: 前方のセンサーの距離で走行を決める\n# 実行: python3 ../RumiCar.py Exercise-3.1.py\n\n\ndef setup():\n    RC_setup()\n\n\ndef loop():\n    d1 = RC_read(CENTER)\n    print(d1)\n    if d1 == -3:            # -3: 範囲外 = 遠い (-3 は数としては最小なので、比較の前にどの距離 (最大 2000) よりも大きい値に置き換える)\n        d1 = 9999\n    if d1 < 300:            # 30 cm より近くに何かある\n        if d1 > 120:\n            RC_drive(FORWARD, 255)\n        elif d1 < 80:\n            RC_drive(REVERSE, 255)\n        else:\n            RC_drive(BRAKE, 255)\n    else:\n        RC_drive(FREE, 0)\n",
    py32: "from RumiCar import *\n\n# 道なりに走る: 3 つのセンサーで速さと向きを決める\n# 実行: python3 ../RumiCar.py Exercise-3.2.py\n\n\ndef setup():\n    RC_setup()\n\n\ndef loop():\n    s0 = RC_read(LEFT)\n    s1 = RC_read(CENTER)\n    s2 = RC_read(RIGHT)\n    print(\"Sensor0:\", s0, \" Sensor1:\", s1, \" Sensor2:\", s2)\n\n    if s0 == -3:            # -3: 範囲外 = 遠い (-3 は数としては最小なので、比較の前にどの距離 (最大 2000) よりも大きい値に置き換える)\n        s0 = 9999\n    if s1 == -3:\n        s1 = 9999\n    if s2 == -3:\n        s2 = 9999\n\n    if s1 < 100:\n        RC_drive(REVERSE, 150)\n    elif s1 < 150:\n        RC_drive(FORWARD, 150)\n    elif s1 < 250:\n        RC_drive(FORWARD, 200)\n    else:\n        RC_drive(FORWARD, 255)\n\n    if s0 > s2:\n        RC_steer(LEFT)\n    else:\n        RC_steer(RIGHT)\n",
    py33: "from RumiCar import *\n\n# なめらかに走る車: Exercise-3.2 の「左右どちらかに必ず切る」の代わりに、\n# 左右の差が小さければまっすぐ (CENTER)、大きければ広い側へ切り、\n# ハンドルの強さを走りながら調整する (効かなければ 1.3 倍、行き過ぎたら半分)\n# 実行: python3 ../RumiCar.py Exercise-3.3.py\n\nipower = 128            # ハンドルの強さ 0〜255 (半分から始める)\nlast_turn = CENTER      # 前回切った側\nlast_gap = 0            # 前回の左右の差 [mm]\n\n\ndef setup():\n    RC_setup()\n    RC_setReadLimit(200)    # RC_read が信じる距離の上限 [mm]。これより先は -3 (遠い)\n\n\ndef loop():\n    global ipower, last_turn, last_gap\n\n    iband = 30          # 左右の差がこれ以下ならまっすぐ [mm]\n    s0 = RC_read(LEFT)\n    s1 = RC_read(CENTER)\n    s2 = RC_read(RIGHT)\n    if s0 == -3:        # -3: 上限より先 = 開けている (-3 は数としては最小なので、先に置き換える)\n        s0 = 250\n    if s1 == -3:\n        s1 = 250\n    if s2 == -3:\n        s2 = 250\n\n    print(\"Sensor0:\", s0, \" Sensor1:\", s1, \" Sensor2:\", s2, \" Power:\", ipower)\n\n    if s0 == -1 or s1 == -1 or s2 == -1:\n        return          # -1: センサーが応答しない。この回は何もせず、前の動きを続ける\n\n    if s1 < 100:        # しきい値は setup() の上限以下にする\n        RC_drive(REVERSE, 150)\n    elif s1 < 150:\n        RC_drive(FORWARD, 150)\n    elif s1 < 200:\n        RC_drive(FORWARD, 200)\n    else:\n        RC_drive(FORWARD, 255)\n\n    gap = abs(s0 - s2)\n    if gap <= iband:\n        RC_steer(CENTER)\n    else:\n        if s0 > s2:\n            side = LEFT\n        else:\n            side = RIGHT\n        if last_turn != CENTER and side != last_turn:\n            ipower = ipower // 2            # 真ん中を越えた: 強すぎるので半分にする\n        elif side == last_turn and gap >= last_gap:\n            ipower = ipower * 13 // 10      # 真ん中に近づいていない: 弱いので 1.3 倍にする\n        ipower = max(40, min(ipower, 255))  # 1.3 倍でまた増やせるよう 40 以上に保つ\n        RC_steer(side, ipower)\n        last_turn = side\n    last_gap = gap\n",
    z2c: "# RumiCar の走行プログラム（見本）\n#\n# このファイルを書き換えることで、独自の走行方法で RumiCar を走行させることができます。\n# 走行管理アプリの「自分のプログラムを送る…」でこのファイルを含むフォルダを選択すると、\n# 車に送信され、そのまま有効化されます（README 11 章「自作の走行プログラム（Python）」）。\n#\n# 使うのは RumiCar ライブラリです。Raspberry Pi 版のライブラリ（RumiCar リポジトリの\n# RasPi/RumiCar.py 0.7.0）そのものを車の本体が使っており、Arduino のライブラリ\n# （RumiCar-lib v0.7.0）とも同じ名前・同じ値です。\n#\n#   setup()   プログラムの開始時に 1 回だけ呼び出されます（省略可）\n#   loop()    50 ミリ秒ごと（20 Hz）に呼び出されます。ここで操舵と駆動を決定します\n#\n#   RC_setReadLimit(上限)            RC_read の値を信頼する距離の上限（mm）を決めます。setup() で 1 回呼びます。\n#                                    上限は 1〜2000、0 は上限なし（既定。2000 mm まで返る）。\n#                                    RC_setReadLimit(方向, 上限) と書くと、その方向（LEFT / CENTER / RIGHT）だけに設定します\n#   RC_read(LEFT / CENTER / RIGHT)   左・前・右の距離センサーの値（mm）\n#                                    0〜上限 = 距離、-1 = 読み取りに失敗、\n#                                    -3 = 範囲外（RC_setReadLimit で決めた上限より先、または対象物なし）。走行では「遠い」として扱います\n#                                    -3 は数としては最も小さいので、比較の前に、RC_read が返すどの距離よりも大きい値に置き換えます\n#   RC_steer(LEFT / CENTER / RIGHT, 強さ)\n#                                    操舵（左・中央・右）。強さは 0〜255 の信号の割合で、省略すると 255（最大）。\n#                                    0 は CENTER と同じ（中立）、CENTER では強さは無視される。\n#                                    補正はしないため、同じ値でも車ごとに舵の効き方は異なる\n#   RC_drive(方向, 値)                駆動。方向は FREE（惰行）/ REVERSE（後退）/ FORWARD（前進）/ BRAKE（ブレーキ）、\n#                                    値は 0〜255 の PWM のデューティ（150 なら全開の 150/255 ≒ 59 % の信号）\n#   RC_params()                      params.json に記述した値（例 RC_params()[\"speed\"]）\n#   RC_state(\"名前\")                 現在の処理状態の名前（走行管理アプリの「判断状態」に表示されます）\n#   print(...)                       車のログに記録されます（ssh で sudo journalctl -u rumicar-core -f）\n#\n# 距離の上限について：センサーのレーザーはコーン状に広がるため、取り付け位置や車高によっては、\n# ある距離から先で床を捉えます。どこまでの値を信頼するかは、ライブラリではなくプログラムが\n# RC_setReadLimit で決めます。この見本は params.json の read_limit_mm を上限にしています\n# （値の決め方は README 5 章「ToF の値を信頼する距離の上限」）。距離のしきい値（stop_mm・turn_mm・\n# side_mm）は上限以下にします。上限より先は -3 になり、しきい値と比べても「遠い」としか分からないためです。\n#\n# RC_steer() と RC_drive() で設定した値は、次に変更するまで保持されます（Arduino と同じ）。\n# この見本の操舵は強さを省略した最大（255）です。強さを変えて走りを滑らかにする例は、\n# RumiCar リポジトリの RasPi/Exercise-3.3（なめらかに走る車）にあります。\n# 安全のため、本体が次の制御を必ず行います。\n#   ・自動モードへの切り替え時は、駆動の許容値を 0 から徐々に増加させる（急発進しない）\n#   ・走行管理アプリの「自動の最大出力」を超えて走行しない\n#   ・loop() の処理時間の上限は 30 ミリ秒。この時間内に処理が完了しなかったフレームはブレーキし、\n#     1 秒以上応答が無ければプログラムを停止する\n#   ・例外が発生したフレームはブレーキする（例外の内容はログに記録される）\n\nfrom RumiCar import *\n\n# -3（範囲外）を比較で「遠い」として扱うための値。RC_read が返すどの距離（最大 2000 mm）よりも\n# 大きいので、read_limit_mm をいくつにしても上限より大きい\nFAR = 9999\n\n\ndef setup():\n    RC_setup()\n    # RC_read の値を信頼する距離の上限（mm）。これより先は -3（遠い）になる。値は params.json の read_limit_mm\n    RC_setReadLimit(RC_params().get(\"read_limit_mm\", 200))\n    RC_state(\"START\")\n    print(\"見本のプログラムを始めます。設定:\", RC_params())\n\n\ndef loop():\n    p = RC_params()                      # params.json の値（車ごとに変更可能）\n    left = RC_read(LEFT)\n    center = RC_read(CENTER)\n    right = RC_read(RIGHT)\n\n    # センサーの読み取りに失敗した場合は停止する\n    if left == -1 or center == -1 or right == -1:\n        RC_drive(BRAKE, 0)\n        RC_state(\"NO_SENSOR\")\n        return\n\n    # 範囲外（-3：上限より先、または対象物なし）は「遠い」\n    if left == -3:\n        left = FAR\n    if center == -3:\n        center = FAR\n    if right == -3:\n        right = FAR\n\n    if center < p[\"stop_mm\"]:\n        # 前方が非常に近い：距離の大きい側と反対へ操舵して後退する（車体の前部が距離の大きい側を向く）\n        if left > right:\n            RC_steer(RIGHT)\n        else:\n            RC_steer(LEFT)\n        RC_drive(REVERSE, p[\"back_speed\"])\n        RC_state(\"BACK\")\n    elif center < p[\"turn_mm\"]:\n        # 前方が近い：距離の大きい側へ操舵し、低速で前進する\n        if left > right:\n            RC_steer(LEFT)\n        else:\n            RC_steer(RIGHT)\n        RC_drive(FORWARD, p[\"slow_speed\"])\n        RC_state(\"TURN\")\n    else:\n        # 前方に余裕がある：左右の壁が近ければ反対側へ操舵し、そうでなければ直進する\n        if left < p[\"side_mm\"]:\n            RC_steer(RIGHT)\n        elif right < p[\"side_mm\"]:\n            RC_steer(LEFT)\n        else:\n            RC_steer(CENTER)\n        RC_drive(FORWARD, p[\"speed\"])\n        RC_state(\"RUN\")\n",
  };
  const oval = buildFromSpec({ name: 'オーバル', kind: 'track', shape: 'ellipse', rx: 1.2, ry: 0.75, width: 0.55 });
  // 実行時エラーは runRace の結果には出ない (fleet.js tickSlot がログに書いて、その車の loop() を止めるだけ・完走しなければ理由は timeout)。
  //   そこで probe で「完走の前に loop() が止まった tick」(stop) を拾う。stop が null なら最後まで loop() が呼ばれ続けた＝実行時エラーなし。
  const race = (src, lang, maxSec, carType = 'normal_fr') => {
    const seq = []; let stop = null;
    const r = runRace({ course: oval, regime: 'tabletop', physics: 'dynamic', laps: 3, maxSec, report: true,
      field: [{ name: 'A', lang, src, carType }], crashRule: { rejoin: true, penaltySec: 3 }, interact: false,
      probe: (tick, slots) => { const c = slots[0].car; seq.push([tick, c.steer, c.steerAmt]); if (stop === null && !slots[0].running && slots[0].lap.laps < 3) stop = tick; } });
    return { r, seq, stop };
  };
  // D1: 2.5 — 指令が変わった tick を拾う。0.5 s ごとに RIGHT255 → LEFT255 → RIGHT128 → LEFT128、1 周 2.05 s (最後の delay は周期＋待ち)。
  for (const [label, src, lang] of [['C (.ino)', EX.ino25, 'c'], ['Python (.py)', EX.py25, 'py']]) {
    const { seq } = race(src, lang, 6);
    const ch = []; let prev = null;
    for (const [tick, d, a] of seq) { const k = `${d}/${a}`; if (k !== prev) { ch.push([tick, k]); prev = k; } }
    const got = ch.slice(0, 8).map(([t, k]) => `${(t / 60).toFixed(2)}s:${k}`).join(' ');
    const want = ['0.00s:2/null', '0.50s:0/null', '1.00s:2/128', '1.50s:0/128', '2.05s:2/null', '2.55s:0/null', '3.05s:2/128', '3.55s:0/128'].join(' ');
    ok(got === want, `D1 Exercise-2.5 ${label}: ${got}`);
  }
  // D2: 3.3 — 実行時エラーなしで走り、強さが 40〜255 の中で変わり、Power を出力する。setup() の RC_setReadLimit(200) (v0.7.0) を通る。
  for (const [label, src, lang] of [['C (.ino)', EX.ino33, 'c'], ['Python (.py)', EX.py33, 'py']]) {
    ok(/RC_setReadLimit\(200\)/.test(src), `D2 Exercise-3.3 ${label}: 本文に RC_setReadLimit(200) がある (v0.7.0 の本文)`);
    const { r, seq, stop } = race(src, lang, 60);
    const amts = new Set(seq.map(([, , a]) => a).filter((a) => a != null));
    const inRange = [...amts].every((a) => a >= 40 && a <= 255 && Number.isInteger(a));
    ok(stop === null, `D2 Exercise-3.3 ${label}: 実行時エラーなし${stop === null ? '' : ' (tick ' + stop + ' で loop() が止まった)'}`);
    ok(amts.size >= 3 && inRange, `D2 Exercise-3.3 ${label}: 強さが変わる (${amts.size} 通り・すべて 40〜255 の整数)`);
    ok(r.logsCount > 100, `D2 Exercise-3.3 ${label}: シリアル出力あり (${r.logsCount} 行)`);
    console.log(`    Exercise-3.3 ${label}: 卓上オーバル 3 周・60 s → 完走 ${r.finishers.length}/1${r.finishers[0] ? ' (' + (r.finishers[0].totalTimeMs / 1000).toFixed(1) + ' s)' : ''}・強さ ${[...amts].sort((a, b) => a - b).slice(0, 12).join(',')}${amts.size > 12 ? ',…' : ''}`);
  }
  // D3: 4.2-Answer (setup() に RC_setReadLimit(200))・RasPi の 3.1／3.2 (上限を決めない＝測距レンジまでの値で判断する) — 実行時エラーなし。
  for (const [label, src, lang, limit] of [['Exercise-4.2-Answer C (.ino)', EX.ino42a, 'c', true], ['RasPi Exercise-3.1 (.py)', EX.py31, 'py', false], ['RasPi Exercise-3.2 (.py)', EX.py32, 'py', false]]) {
    ok(/RC_setReadLimit\(/.test(src) === limit, `D3 ${label}: 本文は RC_setReadLimit を${limit ? '呼ぶ' : '呼ばない'}`);
    const { r, stop } = race(src, lang, 60);
    ok(stop === null, `D3 ${label}: 実行時エラーなし${stop === null ? '' : ' (tick ' + stop + ' で loop() が止まった)'}`);
    ok(r.logsCount > 100, `D3 ${label}: 出力あり (${r.logsCount} 行)`);
    console.log(`    ${label}: 卓上オーバル 3 周・60 s → 完走 ${r.finishers.length}/1${r.finishers[0] ? ' (' + (r.finishers[0].totalTimeMs / 1000).toFixed(1) + ' s)' : ''}`);
  }
  // D4: Zero2Cam v0.7.0 の見本 drive.py — setup() は通る (RC_params() は空の dict なので .get("read_limit_mm", 200) は 200)。loop() は
  //     params.json の値 p["stop_mm"] を読むところで止まる (シミュレータには params.json が無い。v11.x の見本も同じ行の同じ式で止まった)。
  {
    const { env, logs } = mk();
    const ctl = buildController(EX.z2c, 'py', env);
    let setupErr = null, tickErr = null;
    try { ctl.setup(); } catch (e) { setupErr = e; }
    ok(!setupErr && logs.length === 2 && logs[0] === 'state - -> START' && /\{\}$/.test(logs[1]) && !logs.some((l) => /⚠/.test(l)),
      `D4 Zero2Cam drive.py: setup() が通る (RC_setReadLimit(RC_params().get("read_limit_mm", 200))・警告なし・出力 ${logs.length} 行${setupErr ? '・' + setupErr.message : ''})`);
    try { ctl.tick(); } catch (e) { tickErr = e; }
    const line = EX.z2c.split('\n').findIndex((l) => /p\["stop_mm"\]/.test(l)) + 1;
    ok(tickErr && tickErr.i18nKey === 'interp.err.keyError' && tickErr.line === line, `D4 Zero2Cam drive.py: loop() は p["stop_mm"] の行 (${line}) で止まる (${tickErr ? tickErr.message : 'エラーなし'})`);
    // 上限は 200 になっている: 同じ環境で、前の壁を 200 mm と 201 mm に置いて読む
    for (const [mm, want] of [[200, 200], [201, -3]]) {
      const w = mk('tri', wallFor(SENSORS[1], mm));
      const c2 = buildController(EX.z2c, 'py', w.env); c2.setup();
      ok(w.env.RC_read(CONST.CENTER) === want, `D4 Zero2Cam drive.py: setup() の後、前 ${mm} mm は RC_read(CENTER)＝${want} (上限 200)`);
    }
    const { r, stop } = race(EX.z2c, 'py', 5);
    ok(stop !== null && stop <= 3 && r.logsCount === 3, `D4 Zero2Cam drive.py: 本番 runRace でも最初の loop() で止まる (tick ${stop}・出力 ${r.logsCount} 行)＝D2・D3 の「実行時エラーなし」の検査が空振りでない`);
  }
}

// ============================================================================
console.log('\n=== E: 読み込み互換 (Stage BO で足した名前を名前付き import しない・BA1) ===');
{
  const src = (f) => readFileSync('./public/js/' + f, 'utf8');
  const named = (s, mod) => [...s.matchAll(/import\s*\{([^}]*)\}\s*from\s*'([^']+)'/g)].filter((m) => m[2].endsWith(mod)).map((m) => m[1]).join(',');
  const files = ['physics.js', 'physics_dyn.js', 'physics_v2.js', 'api.js', 'race_engine.js', 'runner.js', 'main.js', 'fleet.js', 'loopsched.js', 'interp/evaluator.js'];
  let v = [];
  for (const f of files) {
    const s = src(f);
    if (/\bsteerAdvance\b/.test(named(s, 'config.js'))) v.push(`${f}: steerAdvance`);
    if (/\bPENDING_DELAY\b/.test(named(s, 'evaluator.js'))) v.push(`${f}: PENDING_DELAY`);
    if (/\bloopPeriodAfter\b/.test(named(s, 'fleet.js'))) v.push(`${f}: loopPeriodAfter`);
  }
  ok(v.length === 0, `E1 足した名前を名前付き import していない ${v.length ? '(' + v.join(' / ') + ')' : ''}`);
  // 変異: 名前付き import に足すと検出する (検査の空振りの排除)
  const mut = src('physics.js').replace("steerTargetOf } from './config.js';", "steerTargetOf, steerAdvance } from './config.js';");
  ok(/\bsteerAdvance\b/.test(named(mut, 'config.js')), 'E1 変異 (physics.js が steerAdvance を名前付き import) を検出する');
  ok(/typeof configNS\.steerAdvance === 'function'/.test(src('physics.js')) && /typeof interp\.runLoopFrame !== 'function'/.test(src('runner.js'))
     && /typeof fleetNS\.loopPeriodAfter === 'function'/.test(src('race_engine.js')), 'E2 古いモジュールのときの代わりの経路がある (physics.js・runner.js・race_engine.js)');
}

// ============================================================================
console.log('\n=== F: 引数の数 (Stage BP・正本の def／宣言と同じ数でなければ実行時エラー) ===');
{
  // 1 回 setup()＋tick() して、エラー (文言・種類・行) とログを返す。
  const run = (src, lang) => {
    const { world, env, logs } = mk('tri');
    try { const ctl = buildController(src, lang, env); ctl.setup(); ctl.tick(); return { err: null, logs }; }
    catch (e) { return { err: e, logs }; }
  };
  const PY = (body) => `from RumiCar import *\ndef setup():\n    pass\ndef loop():\n    ${body}\n`;
  const C = (body) => `void setup(){}\nvoid loop(){\n  ${body};\n}\n`;
  // [呼び出し, 渡した数, 受け付ける数の文言]。Python だけの関数は C では試さない。
  const BAD = [['RC_setup(1)', 1, '0', 'both'], ['RC_steer()', 0, '1〜2', 'both'], ['RC_steer(LEFT, 9, 9)', 3, '1〜2', 'both'],
    ['RC_drive(FORWARD)', 1, '2', 'both'], ['RC_drive(FORWARD, 9, 9)', 3, '2', 'both'], ['RC_read()', 0, '1', 'both'],
    ['RC_read(LEFT, 1)', 2, '1', 'both'], ['RC_wheel_speed()', 0, '1', 'both'], ['RC_params(1)', 1, '0', 'py'], ['RC_state()', 0, '1', 'py'],
    ['RC_setReadLimit()', 0, '1〜2', 'both'], ['RC_setReadLimit(LEFT, 200, 1)', 3, '1〜2', 'both']];   // Stage BQ (正本は TypeError: takes 1 or 2 arguments)
  for (const [call, n, want, langs] of BAD) {
    for (const lang of langs === 'py' ? ['py'] : ['py', 'c']) {
      const r = run(lang === 'py' ? PY(call) : C(call), lang);
      const fn = call.slice(0, call.indexOf('('));
      const [lo, hi] = want.includes('〜') ? want.split('〜').map(Number) : [Number(want), Number(want)];
      const pr = r.err ? r.err.i18nParams || {} : {};
      ok(r.err && r.err.i18nKey === 'interp.err.argCount' && r.err.i18nMsgKey === (lo === hi ? 'interp.err.argCount' : 'interp.err.argRange')
        && r.err.line === (lang === 'py' ? 5 : 3) && pr.fn === fn && pr.n === n && pr.min === lo && pr.max === hi && r.err.message.includes(`${fn}()`),
        `F1 ${lang} ${call} → argCount・呼び出しの行 (${r.err ? r.err.message : 'エラーなし'})`);
    }
  }
  // `import RumiCar` の形 (モジュールオブジェクト経由) も同じ
  {
    const r = run('import RumiCar\ndef setup():\n    pass\ndef loop():\n    RumiCar.RC_drive(RumiCar.FORWARD)\n', 'py');
    ok(r.err && r.err.i18nKey === 'interp.err.argCount' && r.err.line === 5, `F2 py RumiCar.RC_drive(FORWARD) → argCount (${r.err ? r.err.message : 'エラーなし'})`);
  }
  // 正しい数はエラーにならない (1 引数・2 引数の RC_steer を含む)
  {
    const p = run('from RumiCar import *\ndef setup():\n    RC_setup()\n    RC_setReadLimit(200)\n    RC_setReadLimit(LEFT, 300)\ndef loop():\n    RC_steer(LEFT)\n    RC_steer(RIGHT, 100)\n    RC_drive(FORWARD, 100)\n    x = RC_read(CENTER)\n    w = RC_wheel_speed(FRONT)\n    RC_state("RUN")\n    q = RC_params()\n', 'py');
    ok(!p.err, `F3 py 正しい数の呼び出しはエラーにならない (${p.err ? p.err.message : ''})`);
    const c = run('void setup(){ RC_setup(); RC_setReadLimit(200); RC_setReadLimit(LEFT, 300); }\nvoid loop(){ RC_steer(LEFT); RC_steer(RIGHT, 100); RC_drive(FORWARD, 100); int x = RC_read(CENTER); float w = RC_wheel_speed(FRONT); }\n', 'c');
    ok(!c.err, `F3 c 正しい数の呼び出しはエラーにならない (${c.err ? c.err.message : ''})`);
  }
  // JS は従来どおり (足りない引数は 0 として警告して続ける)
  {
    const j = run('function setup(){}\nfunction loop(){ RC_drive(FORWARD); }\n', 'js');
    ok(!j.err && j.logs.some((l) => /RC_drive/.test(l)), `F4 js RC_drive(FORWARD) は従来どおり警告して続ける (${j.err ? j.err.message : JSON.stringify(j.logs)})`);
    // Stage BQ: JS の RC_setReadLimit() (引数なし) は「上限を省略」＝上限なしとして警告 1 回・戻り値 1。3 個目以降は使わない (方向と上限の 2 個の形)。
    const k = run('function setup(){ Serial.println(RC_setReadLimit()); Serial.println(RC_setReadLimit()); Serial.println(RC_setReadLimit(CENTER, 150, 9)); }\nfunction loop(){}\n', 'js');
    ok(!k.err && k.logs.filter((l) => /⚠/.test(l)).length === 1 && k.logs.filter((l) => !/⚠/.test(l)).join(',') === '1,1,1',
      `F4 js RC_setReadLimit() は上限なしとして警告 1 回・3 個目の引数は使わない (${k.err ? k.err.message : JSON.stringify(k.logs)})`);
  }
  // BA1: ARITY を名前付き import しない (古い evaluator.js がキャッシュに残るブラウザでも api.js が読める)
  {
    const a = readFileSync('./public/js/api.js', 'utf8');
    const named = [...a.matchAll(/import\s*\{([^}]*)\}\s*from\s*'([^']+)'/g)].filter((m) => m[2].endsWith('evaluator.js')).map((m) => m[1]).join(',');
    ok(!/\bARITY\b/.test(named) && /interpNS\.ARITY/.test(a), 'F5 api.js は ARITY を名前空間から読む (名前付き import しない)');
  }
}

// ============================================================================
console.log('\n=== G: RC_setReadLimit と RC_read (Stage BQ・正本 RasPi RumiCar.py ' + RASPI.version + ' の表と照合) ===');
{
  const L = RASPI.limit, RAW = L.raw;
  const DEF = { L: SENSORS[0], C: SENSORS[1], R: SENSORS[2], B: SENSOR_REAR }, DIR = { L: CONST.LEFT, C: CONST.CENTER, R: CONST.RIGHT, B: CONST.REAR };
  const rawWant = (raw) => (raw < 0 || raw > SENSOR_RANGE.maxMm ? 8190 : raw);   // 生読取: 壁なし・測距レンジ超は 8190
  const callHost = (env, c) => (c === '__RC_setup__' ? (env.RC_setup(), null) : env.RC_setReadLimit(...c.map(dec)));
  const showCalls = (calls) => calls.map((c) => (c === '__RC_setup__' ? 'RC_setup()' : `RC_setReadLimit(${c.map(show).join(', ')})`)).join('; ');

  // G1: ホストの関数を直接呼ぶ。表の全部 (呼び出しの列 × 生の値 × 3 方向)。壁は本番の測距 (sensors.js readAll) に測らせる。
  {
    let n = 0, bad = 0, rawBad = 0;
    for (const c of L.cases) for (const k of ['L', 'C', 'R']) RAW.forEach((raw, i) => {
      const { env, logs } = mk('tri', wallFor(DEF[k], raw));
      const rets = c.calls.map((x) => callHost(env, x));
      if (env['sensor' + DIR[k]].readRangeSingleMillimeters() !== rawWant(raw)) rawBad++;   // 壁の位置が狙った生の値になっている・上限の影響を受けない
      const got = env.RC_read(DIR[k]), rear = env.RC_read(CONST.REAR);
      n++;
      if (got !== c.read[k][i] || rear !== c.read.B || JSON.stringify(rets) !== JSON.stringify(c.rets) || logs.length !== c.warns) {
        bad++; if (bad <= 5) console.log(`    ${showCalls(c.calls)} ・${k} の生の値 ${raw}: sim RC_read=${got} 戻り値 ${JSON.stringify(rets)} 警告 ${logs.length} / 正本 RC_read=${c.read[k][i]} 戻り値 ${JSON.stringify(c.rets)} 警告 ${c.warns}`);
      }
    });
    ok(L.cases.length >= 100 && bad === 0, `G1 RC_setReadLimit の呼び出しの列 ${L.cases.length} 通り × 生の値 ${RAW.length} 通り × 3 方向: ${n - bad}/${n} が正本と同じ戻り値・警告の数・RC_read`);
    ok(rawBad === 0, `G1 生読取 sensorN.readRangeSingleMillimeters() は置いた壁の距離そのまま (上限の影響を受けない・測距レンジ超と壁なしは 8190)・不一致 ${rawBad}`);
    // 表に要点が入っていること (表が痩せたら赤): 既定・上限ちょうど・上限+1・測距レンジ・方向ごと・不正な方向・0／負・収める・切り捨て・RC_setup
    const find = (calls) => L.cases.find((c) => JSON.stringify(c.calls) === JSON.stringify(calls));
    const at = (c, k, raw) => c.read[k][RAW.indexOf(raw)];
    const d0 = find([[0]]), d200 = find([[200]]), l300 = find([[0, 300]]), bad5 = find([[200], [5, 100]]), su = find([[200], '__RC_setup__']);
    ok(d0 && [0, 200, 201, 2000].every((r) => at(d0, 'C', r) === r) && at(d0, 'C', 2001) === -3 && at(d0, 'C', 8190) === -3 && at(d0, 'C', -3) === -3 && d0.read.B === -1,
      'G1 表: 上限なしは 0→0・200→200・201→201・2000→2000・2001／8190／範囲外→-3・後方センサーなしの REAR→-1');
    ok(d200 && at(d200, 'L', 200) === 200 && at(d200, 'L', 201) === -3 && at(d200, 'R', 200) === 200 && at(d200, 'R', 201) === -3, 'G1 表: 上限 200 (全方向) は 200→200・201→-3');
    ok(l300 && at(l300, 'L', 300) === 300 && at(l300, 'L', 301) === -3 && at(l300, 'C', 301) === 301 && at(l300, 'R', 2000) === 2000, 'G1 表: LEFT だけ 300 は 300→300・301→-3・ほかの方向は元のまま');
    ok(bad5 && bad5.rets.join() === '1,0' && at(bad5, 'C', 200) === 200 && at(bad5, 'C', 201) === -3, 'G1 表: 不正な方向は戻り値 0 で何も変えない');
    ok([[4, 200], [5, 200], [-1, 200], [{ bool: true }, 200]].every((c) => { const e = find([c]); return e && e.rets[0] === 0 && at(e, 'C', 2000) === 2000; }), 'G1 表: 方向 4・5・-1・True は戻り値 0');
    ok([[[-5]], [[2001]], [[32767]], [[{ none: true }]]].every((c) => { const e = find(c); return e && e.rets[0] === 1 && at(e, 'C', 2000) === 2000; }) && find([[{ none: true }]]).warns === 1 && find([[2001]]).warns === 0,
      'G1 表: 負・2001・32767・None は上限なしと同じ値 (None だけ警告 1 回)');
    ok(at(find([[1]]), 'C', 1) === 1 && at(find([[1]]), 'C', 2) === -3 && at(find([[200.9]]), 'C', 200) === 200 && at(find([[200.9]]), 'C', 201) === -3, 'G1 表: 上限 1 は 1→1・2→-3、200.9 は 200');
    ok(su && at(su, 'C', 201) === -3 && find([[3, 100]]).rets[0] === 1 && find([[3, 100]]).read.B === -1, 'G1 表: RC_setup は上限を変えない・REAR は後方センサーなしでも設定でき RC_read(REAR) は -1 のまま');
  }

  // G2: 後方センサーあり／なしの車 (正本は pigpio 用の層)。RC_read(LEFT)・RC_read(REAR)・不正な方向。
  {
    let n = 0, bad = 0;
    for (const c of L.pigpio) {
      for (const k of ['L', 'B']) RAW.forEach((raw, i) => {
        const { env } = mk('tri', wallFor(DEF[k], raw), c.rear);
        const rets = c.calls.map((x) => callHost(env, x));
        const got = env.RC_read(DIR[k]); n++;
        if (got !== c.read[k][i] || JSON.stringify(rets) !== JSON.stringify(c.rets)) { bad++; if (bad <= 5) console.log(`    後方センサー${c.rear ? 'あり' : 'なし'} ${showCalls(c.calls)} ・${k} の生の値 ${raw}: sim ${got} / 正本 ${c.read[k][i]}`); }
      });
      const { env } = mk('tri', [], c.rear);
      const bd = [env.RC_read(4), env.RC_read(-1), env.RC_read(true), env.RC_read(null)];
      n++; if (JSON.stringify(bd) !== JSON.stringify(c.read.badDir)) { bad++; console.log(`    不正な方向: sim ${bd} / 正本 ${c.read.badDir}`); }
    }
    ok(L.pigpio.some((c) => c.rear) && L.pigpio.some((c) => !c.rear) && bad === 0, `G2 後方センサーあり／なしの車 ${L.pigpio.length} 通り: ${n - bad}/${n} が正本と同じ (REAR の上限・未装備は -1・方向 4／-1／True／None は -2)`);
  }

  // G3: C・Python・JavaScript の処理系を通す。値をその言語で書けない呼び出しは試さない (C: None・True・NaN・inf・list)。
  //     プログラム: setup() で呼び出しの列の戻り値を 1 行ずつ出力し、loop() で RC_read(LEFT／CENTER／RIGHT／REAR) を 1 行ずつ出力する。
  {
    const lit = {
      py: (v) => (v === null ? 'None' : typeof v === 'boolean' ? (v ? 'True' : 'False') : Array.isArray(v) ? JSON.stringify(v) : typeof v === 'string' ? JSON.stringify(v)
        : Number.isNaN(v) ? 'math.nan' : v === Infinity ? 'math.inf' : v === -Infinity ? '-math.inf' : String(v)),
      c: (v) => (typeof v === 'string' ? JSON.stringify(v) : typeof v === 'number' && Number.isFinite(v) ? String(v) : null),
      js: (v) => (v === null ? 'null' : Array.isArray(v) ? JSON.stringify(v) : typeof v === 'string' ? JSON.stringify(v) : String(v)),
    };
    const prog = (lang, calls) => {
      const stm = [];
      for (const c of calls) {
        if (c === '__RC_setup__') { stm.push('RC_setup()'); continue; }
        const a = c.map((x) => lit[lang](dec(x)));
        if (a.includes(null)) return null;
        stm.push(lang === 'py' ? `print(RC_setReadLimit(${a.join(', ')}))` : `Serial.println(RC_setReadLimit(${a.join(', ')}))`);
      }
      const reads = ['LEFT', 'CENTER', 'RIGHT', 'REAR'];
      if (lang === 'py') return `from RumiCar import *\nimport math\n\ndef setup():\n${stm.map((x) => '    ' + x).join('\n')}\n\ndef loop():\n${reads.map((d) => `    print(RC_read(${d}))`).join('\n')}\n`;
      const fn = lang === 'c' ? 'void' : 'function';
      return `${fn} setup() {\n${stm.map((x) => '  ' + x + ';').join('\n')}\n}\n${fn} loop() {\n${reads.map((d) => `  Serial.println(RC_read(${d}));`).join('\n')}\n}\n`;
    };
    for (const lang of ['c', 'py', 'js']) {
      let n = 0, bad = 0, cases = 0;
      for (const c of L.cases) {
        const src = prog(lang, c.calls);
        if (!src) continue;
        cases++;
        for (const k of ['L', 'C', 'R']) RAW.forEach((raw, i) => {
          const { env, logs } = mk('tri', wallFor(DEF[k], raw));
          let err = null;
          try { const ctl = buildController(src, lang, env); ctl.setup(); ctl.tick(); } catch (e) { err = e; }
          const out = logs.filter((l) => !/⚠/.test(l)), warns = logs.length - out.length;
          const nCall = c.calls.filter((x) => x !== '__RC_setup__').length;
          const rets = out.slice(0, nCall).map(Number), reads = out.slice(nCall).map(Number);
          const wantRets = c.rets.filter((r) => r !== null);
          n++;
          if (err || JSON.stringify(rets) !== JSON.stringify(wantRets) || warns !== c.warns || reads.length !== 4 || reads[DIR[k]] !== c.read[k][i] || reads[3] !== c.read.B) {
            bad++; if (bad <= 5) console.log(`    ${lang} ${showCalls(c.calls)} ・${k} の生の値 ${raw}: ${err ? err.message : `戻り値 ${rets} 警告 ${warns} RC_read ${reads}`} / 正本 戻り値 ${wantRets} 警告 ${c.warns} RC_read(${k})=${c.read[k][i]}`);
          }
        });
      }
      ok(cases >= (lang === 'c' ? 60 : L.cases.length) && bad === 0, `G3 ${lang === 'c' ? 'C++' : lang === 'py' ? 'Python' : 'JavaScript'} の処理系: 呼び出しの列 ${cases} 通り × 生の値 × 3 方向 ${n - bad}/${n} が正本と同じ`);
    }
    // `import RumiCar` → RumiCar.RC_setReadLimit(...) の形・正本の __all__ と同じ名前
    const { env, logs } = mk('tri', wallFor(DEF.C, 201));
    const ctl = buildController('import RumiCar\ndef setup():\n    print(RumiCar.RC_setReadLimit(200))\n    print(RumiCar.RC_setReadLimit(RumiCar.LEFT, 300))\ndef loop():\n    print(RumiCar.RC_read(RumiCar.CENTER))\n', 'py', env);
    ctl.setup(); ctl.tick();
    ok(logs.join(',') === '1,1,-3', `G3 Python: import RumiCar → RumiCar.RC_setReadLimit(...) の形でも同じ (${logs.join(',')})`);
    const py = pythonEnv(env);
    ok(JSON.stringify(Object.keys(py.RumiCar)) === JSON.stringify(RASPI.all) && RASPI.all.every((k) => k in py),
      `G3 Python に見せる RumiCar の名前は正本の __all__ と同じ (${RASPI.all.length} 個・RC_setReadLimit を含む)`);
    ok(typeof env.RC_setReadLimit === 'function' && !('RC_params' in env), 'G3 C++／JavaScript の環境にも RC_setReadLimit がある (RC_params・RC_state は Python だけ)');
  }

  // G4: 走行ごとに上限なしへ戻る。本番 (main.js の ▶・race_engine.js の runRace) は走行を始めるたびに buildApi を呼び直すので、
  //     同じ車 (world) で buildApi を呼び直した後は上限が残っていないことと、その配線 (buildController より前に buildApi) を見る。
  {
    const first = mk('tri', wallFor(DEF.C, 500));
    const c1 = buildController('void setup(){ RC_setup(); RC_setReadLimit(200); }\nvoid loop(){ Serial.println(RC_read(CENTER)); }\n', 'c', first.env); c1.setup(); c1.tick();
    const env2 = buildApi(first.world);   // 次の走行 (同じ world)
    const c2 = buildController('void setup(){ RC_setup(); }\nvoid loop(){ Serial.println(RC_read(CENTER)); }\n', 'c', env2); c2.setup(); c2.tick();
    ok(first.logs.join(',') === '-3,500', `G4 前の走行で決めた上限は次の走行に残らない (1 回目 上限 200 → ${first.logs[0]}・2 回目 上限を決めない → ${first.logs[1]})`);
    const main = readFileSync('./public/js/main.js', 'utf8'), eng = readFileSync('./public/js/race_engine.js', 'utf8');
    const startAuto = main.slice(main.indexOf('function startAuto()'), main.indexOf('function stopAuto()'));
    const wired = (t) => { const a = t.indexOf('.hostEnv = buildApi('), b = t.indexOf('buildController('); return a > 0 && b > a; };
    ok(wired(startAuto) && wired(eng.slice(eng.indexOf('rebuildSpawns(slots, course, gridUsed'))), 'G4 ▶ (main.js startAuto) と runRace は、プログラムを組み立てる前に走行ごとに buildApi を呼び直す (配線)');
    // 本番 runRace を 2 回: 1 回目は上限 200、2 回目は上限を決めない同じ判定。上限が残っていれば 2 回目も 1 回目と同じ軌跡になる。
    const oval = buildFromSpec({ name: 'オーバル', kind: 'track', shape: 'ellipse', rx: 1.2, ry: 0.75, width: 0.55 });
    const SRC = (lim) => `void setup(){ RC_setup(); ${lim} }\nvoid loop(){ int c = RC_read(CENTER); if (c == -3) { RC_steer(LEFT); RC_drive(FORWARD, 90); } else { RC_steer(CENTER); RC_drive(FORWARD, 160); } }\n`;
    const go = (lim) => runRace({ course: oval, regime: 'tabletop', physics: 'dynamic', laps: 1, trace: true, maxSec: 5, field: [{ name: 'A', lang: 'c', src: SRC(lim), carType: 'normal_fr' }], crashRule: { rejoin: true, penaltySec: 3 }, interact: false }).traceHash;
    const a = go('RC_setReadLimit(200);'), b = go(''), a2 = go('RC_setReadLimit(200);'), b2 = go('');
    ok(a !== b && a === a2 && b === b2, `G4 本番 runRace: 上限 200 の走行 (${a}) の後でも、上限を決めない走行は同じ軌跡 (${b}＝${b2})・2 つは違う軌跡`);
  }

  // G5: 領域。どの領域もライブラリの側の一律の打ち切りが無く (v11.x は卓上 200・中スケール 400)、RC_read は測距レンジまでを返す。
  //     上限はプログラムに書いた mm のまま (領域でスケールしない)。収める上側の端は領域の測距レンジ (卓上は実機と同じ 2000)。
  {
    for (const [regime, range] of [['tabletop', 2000], ['midscale', 4000], ['fullscale', 150000]]) {
      applyRegime(regime);
      ok(RC_READ_RANGE.maxMm === 0 && REGIMES[regime].rcReadMaxMm === 0 && SENSOR_RANGE.maxMm === range, `G5 ${regime}: 一律の打ち切りなし (rcReadMaxMm=${REGIMES[regime].rcReadMaxMm})・測距レンジ ${SENSOR_RANGE.maxMm} mm`);
      const read = (mm, ...lim) => { const { env } = mk('tri', wallFor(SENSORS[1], mm)); if (lim.length) env.RC_setReadLimit(...lim); return env.RC_read(CONST.CENTER); };
      const pts = [201, 401, range - 1, range];
      ok(pts.every((mm) => read(mm) === mm) && read(range + 1) === -3, `G5 ${regime}: 上限を決めなければ ${pts.join('・')} mm はそのまま・測距レンジ超は -3`);
      ok(read(300, 300) === 300 && read(301, 300) === -3, `G5 ${regime}: 上限 300 は 300→300・301→-3 (プログラムに書いた mm のまま)`);
      ok(read(range, range + 5000) === range && read(range, 1e30) === range && read(range - 1, range - 1) === range - 1 && read(range, range - 1) === -3,
        `G5 ${regime}: 測距レンジより大きい上限は測距レンジに収まる (上限なしと同じ値)・測距レンジ−1 は効く`);
    }
    applyRegime('tabletop');
    // センサーノイズ ON: 測距レンジの端の壁は、ノイズで生の値がレンジより上へ振れる。RC_read が返す距離は測距レンジを超えない (超えた分は -3・
    //   正本の「2000 mm を超える値は -3」)。生読取は振れた値のまま。乱数は決まった列に差し替える (結果を毎回同じにするため。検査の後に戻す)。
    const sav = { on: SENSOR_NOISE.on, dropout: SENSOR_NOISE.dropout, rnd: Math.random };
    let seed = 12345; Math.random = () => { seed = (Math.imul(seed, 1103515245) + 12345) >>> 0; return (seed + 0.5) / 4294967296; };
    SENSOR_NOISE.on = true; SENSOR_NOISE.dropout = 0;
    const range = SENSOR_RANGE.maxMm, { world, env } = mk('tri', wallFor(SENSORS[1], range));
    let over = 0, rawOver = 0, minus3 = 0, n = 0;
    for (let k = 0; k < 400; k++) {
      world._sensGen++;
      const raw = env.sensor1.readRangeSingleMillimeters(); world._sensGen++;
      const v = env.RC_read(CONST.CENTER); n++;
      if (raw > range && raw !== 8190) rawOver++;
      if (v > range) over++; else if (v === -3) minus3++;
    }
    SENSOR_NOISE.on = sav.on; SENSOR_NOISE.dropout = sav.dropout; Math.random = sav.rnd;
    ok(over === 0 && minus3 > 50 && rawOver > 50, `G5 センサーノイズ ON・測距レンジの端の壁: RC_read は測距レンジを超える値を返さない (${n} 回のうち超えた値 ${over}・-3 ${minus3} 回・生読取がレンジを超えた ${rawOver} 回)`);
  }

  // G6: 警告は同じ値につき 1 回 (方向・上限)。正しい値では出さない。表示言語の文言に関数名と値が入る。
  {
    const { env, logs } = mk();
    env.RC_setReadLimit(200); env.RC_setReadLimit(CONST.LEFT, 300); env.RC_setReadLimit(0); env.RC_setReadLimit(2001); env.RC_setReadLimit(-1); env.RC_setReadLimit(200.9);
    ok(logs.length === 0, `G6 正しい値・収まる値では警告を出さない (${logs.length} 件)`);
    for (let i = 0; i < 3; i++) env.RC_setReadLimit('abc');
    for (let i = 0; i < 3; i++) env.RC_setReadLimit(CONST.LEFT, 'abc');
    ok(logs.length === 1 && /RC_setReadLimit/.test(logs[0]) && /abc/.test(logs[0]), `G6 数にできない上限の警告は同じ値につき 1 回 (${logs.length} 件)`);
    for (let i = 0; i < 3; i++) env.RC_setReadLimit(7, 100);
    env.RC_setReadLimit(true, 100); env.RC_setReadLimit(7, 'zzz');
    ok(logs.length === 3 && /RC_setReadLimit/.test(logs[1]) && /LEFT \/ CENTER \/ RIGHT \/ REAR/.test(logs[1]), `G6 方向の誤りも値ごとに 1 回・方向が不正なら上限の値は見ない (${logs.length} 件)`);
  }

  // G7: 読み込み互換 (BA1) — api.js は Stage BQ で config.js・evaluator.js から新しい名前を名前付き import していない
  //     (SENSOR_RANGE・RC_READ_RANGE は以前からある名前)。config.js・evaluator.js に Stage BQ で足した export は無い。
  {
    const a = readFileSync('./public/js/api.js', 'utf8');
    const named = (mod) => [...a.matchAll(/import\s*\{([^}]*)\}\s*from\s*'([^']+)'/g)].filter((m) => m[2].endsWith(mod)).flatMap((m) => m[1].split(',').map((x) => x.trim())).sort().join(',');
    ok(named('config.js') === 'CONST,RC_READ_RANGE,SENSOR_HOLD,SENSOR_NOISE,SENSOR_RANGE,SIM' && named('evaluator.js') === 'ONE_ARG,RuntimeError,typeName',
      `G7 api.js が名前付き import する名前は以前からある名前だけ (config.js: ${named('config.js')}／evaluator.js: ${named('evaluator.js')})`);
  }
}

console.log(`\n[結果] pass=${pass} fail=${fail}`);
process.exit(fail ? 1 : 0);
